{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "Organization",
            "@id": "http://www.unep.org/#organization",
            "description": "The global authority for the environment with programmes focusing on climate, nature, pollution, sustainable development and more.",
            "name": "United Nations Environment Programme",
            "url": "http://www.unep.org",
            "logo": {
                "@type": "ImageObject",
                "url": "http://www.unep.org/themes/custom/unep_corporate/logo.svg"
            }
        },
        {
            "@type": "WebPage",
            "@id": "http://www.unep.org/en/whats-new/news-stories-speeches",
            "description": "UNEP - UN Environment Programme",
            "publisher": {
                "@type": "Organization",
                "@id": "http://www.unep.org/#organization",
                "name": "United Nations Environment Programme",
                "url": "http://www.unep.org"
            }
        }
    ]
}
